<?php require_student();$me=student();$search=trim($_GET['search']??'');$status=$_GET['status']??'';$sql='SELECT c.*,ca.category_name FROM complaints c JOIN categories ca ON ca.id=c.category_id WHERE c.student_id=?';$types='i';$params=[$me['id']];if($search!==''){$sql.=' AND (c.title LIKE ? OR c.complaint_id LIKE ?)';$term="%$search%";$types.='ss';$params[]=$term;$params[]=$term;}if(in_array($status,['Pending','In Progress','Resolved','Closed','Rejected'],true)){$sql.=' AND c.status=?';$types.='s';$params[]=$status;}$sql.=' ORDER BY c.created_at DESC';$rows=db_all($sql,$types,$params);$pageTitle='My Complaints';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4"><div class="d-flex justify-content-between align-items-center gap-3 flex-wrap"><div><div class="small-muted">STUDENT PORTAL</div><h1 class="section-title mb-0">My complaints</h1></div><a class="btn btn-primary" href="<?=e(url('student/submit.php'))?>">+ New complaint</a></div></div><div class="card mb-4"><div class="card-body"><form class="row g-2"><div class="col-md-6"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Search by ID or title"></div><div class="col-md-4"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Pending','In Progress','Resolved','Closed','Rejected'] as $option): ?><option <?=($status===$option)?'selected':''?>><?=e($option)?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form></div></div><div class="card"><div class="table-responsive"><?php if(!$rows): ?><div class="empty-state">No complaints match your search.</div><?php else: ?><table class="table"><thead><tr><th>Complaint</th><th>Category</th><th>Priority</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><a class="complaint-id" href="<?=e(url('student/complaint.php?id='.$row['id']))?>"><?=e($row['complaint_id'])?></a><div><?=e($row['title'])?></div></td><td><?=e($row['category_name'])?></td><td><span class="fw-semibold <?=e(priority_class($row['priority']))?>"><?=e($row['priority'])?></span></td><td><span class="badge-soft <?=e(status_class($row['status']))?>"><?=e($row['status'])?></span></td><td class="small-muted"><?=e(date('d M Y',strtotime($row['updated_at'])))?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></div></div></div>
